begin;

-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_parent_skill_id uuid;
  v_internal_parent_snapshot jsonb;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  if exists (
    select 1 from public.learning_curriculum_skills
     where catalog_id = v_catalog_id and code = 'LANGUAGES_AREA'
       and metadata->>'content_pack' not in ('tec-escola-knowledge-expansion-v3', 'TECESCOLA_CORE_V5_QUESTION_FIRST')
  ) then raise exception 'V5_INTERNAL_PARENT_ANCHOR_CODE_COLLISION:LANGUAGES_AREA'; end if;
  insert into public.learning_curriculum_skills as existing(
    catalog_id, code, stage, grade_level, subject_area, domain, title, description,
    active, node_kind, content_readiness, mastery_targetable, pedagogical_review_status,
    publication_status, bncc_alignment_status, metadata
  ) values (
    v_catalog_id, 'LANGUAGES_AREA', 'ENSINO_MEDIO', 1, 'LANGUAGES', 'V3_INTERNAL_ANCHOR',
    'Linguagens e producao de sentidos', 'Agrupador interno de área; não cria equivalência oficial nem componente institucional.', false, 'ANCHOR', 'GRAPH_ONLY', false,
    'PEDAGOGICAL_REVIEW_PENDING', 'STAGING', 'CANDIDATE', '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","source_pack":"tec-escola-knowledge-expansion-v3","source_unit_id":"V3_LANGUAGES_MULTIMODAL_HS","internal_grouping_only":true,"official_code":null,"bncc_alignment":"NOT_CLAIMED","official_mapping_status":"NOT_CLAIMED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","mastery_targetable":false}'::jsonb
  ) on conflict (catalog_id, code) do update
    set publication_status = 'STAGING'
    where existing.stage = 'ENSINO_MEDIO'
      and existing.grade_level = 1
      and existing.subject_area = 'LANGUAGES'
      and existing.domain = 'V3_INTERNAL_ANCHOR'
      and existing.active = false
      and existing.node_kind = 'ANCHOR'
      and existing.content_readiness = 'GRAPH_ONLY'
      and existing.mastery_targetable = false
      and existing.pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING'
      and existing.bncc_alignment_status = 'CANDIDATE'
      and existing.metadata->>'content_pack' in ('tec-escola-knowledge-expansion-v3', 'TECESCOLA_CORE_V5_QUESTION_FIRST')
      and existing.metadata->>'internal_grouping_only' = 'true'
      and existing.metadata->>'bncc_alignment' = 'NOT_CLAIMED'
      and existing.metadata->>'official_code' is null
      and (existing.metadata->>'official_mapping_status' = 'NOT_CLAIMED'
        or existing.metadata->>'mapping_status' = 'MAPPING_PENDING')
      and existing.publication_status in ('PUBLISHED', 'STAGING');
  if not exists (
    select 1 from public.learning_curriculum_skills
     where catalog_id = v_catalog_id and code = 'LANGUAGES_AREA'
       and stage = 'ENSINO_MEDIO' and grade_level = 1
       and subject_area = 'LANGUAGES' and domain = 'V3_INTERNAL_ANCHOR'
       and active = false and node_kind = 'ANCHOR' and content_readiness = 'GRAPH_ONLY'
       and mastery_targetable = false and pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING'
       and bncc_alignment_status = 'CANDIDATE'
       and publication_status = 'STAGING'
       and metadata->>'internal_grouping_only' = 'true'
       and metadata->>'bncc_alignment' = 'NOT_CLAIMED'
       and metadata->>'official_code' is null
       and (metadata->>'official_mapping_status' = 'NOT_CLAIMED'
         or metadata->>'mapping_status' = 'MAPPING_PENDING')
       and metadata->>'publication_status' = 'STAGING'
       and metadata->>'content_pack' in ('tec-escola-knowledge-expansion-v3', 'TECESCOLA_CORE_V5_QUESTION_FIRST')
  ) then
    select jsonb_build_object(
      'stage', stage, 'grade_level', grade_level, 'subject_area', subject_area, 'domain', domain,
      'active', active, 'node_kind', node_kind, 'content_readiness', content_readiness,
      'mastery_targetable', mastery_targetable, 'pedagogical_review_status', pedagogical_review_status,
      'bncc_alignment_status', bncc_alignment_status, 'content_pack', metadata->>'content_pack',
      'internal_grouping_only', metadata->>'internal_grouping_only', 'bncc_alignment', metadata->>'bncc_alignment',
      'official_code', metadata->>'official_code', 'official_mapping_status', metadata->>'official_mapping_status',
      'mapping_status', metadata->>'mapping_status', 'publication_status_column', publication_status,
      'publication_status_metadata', metadata->>'publication_status'
    ) into v_internal_parent_snapshot
      from public.learning_curriculum_skills
     where catalog_id = v_catalog_id and code = 'LANGUAGES_AREA';
    raise exception 'V5_INTERNAL_PARENT_ANCHOR_SCOPE_CONFLICT:LANGUAGES_AREA:%', coalesce(v_internal_parent_snapshot::text, 'MISSING');
  end if;
  select id into v_parent_skill_id from public.learning_curriculum_skills where catalog_id = v_catalog_id and code = 'LANGUAGES_AREA';
  if v_parent_skill_id is null then raise exception 'V5_INTERNAL_SKILL_PARENT_MISSING:LANGUAGES_AREA'; end if;
  insert into public.learning_curriculum_skills as existing(
    catalog_id, code, stage, grade_level, subject_area, domain, title, description,
    active, node_kind, content_readiness, mastery_targetable, parent_canonical_skill_id,
    pedagogical_review_status, publication_status, bncc_alignment_status, metadata
  ) values (
    v_catalog_id, 'LANGUAGES_CREATE_COLLABORATIVELY_HS', 'ENSINO_MEDIO', 1, 'LANGUAGES', 'LINGUAGENS_MULTISSEMIOTICAS',
    'Planejar producao colaborativa em diferentes linguagens', 'Participa de processos de criação individual e colaborativa, selecionando linguagens e recursos para produzir sentidos em contexto definido.', false, 'LEAF', 'ADAPTIVE_READY', false, v_parent_skill_id,
    'PEDAGOGICAL_REVIEW_PENDING', 'STAGING', 'CANDIDATE', '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-languages-collaboration","source_pack":"tec-escola-knowledge-expansion-v3","source_candidate":"LINGUAGENS_UNSPECIFIED_TEXT_LANGUAGE","source_unit_id":"V3_LANGUAGES_MULTIMODAL_HS","internal_skill_code":"LANGUAGES_CREATE_COLLABORATIVELY_HS","grade_from":1,"grade_to":3,"official_source_reference":{"officialCode":"EM13LGG301","sourceId":"BNCC_EM_2018","documentVersion":"BNCC Ensino Médio, versão homologada 2018","url":"https://basenacionalcomum.mec.gov.br/images/historico/BNCC_EnsinoMedio_embaixa_site_110518.pdf","page":61,"section":"LGG > Habilidades","officialDescription":"Participar de processos de produção individual e colaborativa em diferentes linguagens (artísticas, corporais e verbais), levando em conta seus funcionamentos, para produzir sentidos em diferentes contextos.","localCatalogExcerpt":") Participar de processos de produção individual e colaborativa em diferentes linguagens (artísticas, corporais e verbais), levando em conta seus funcionamentos, para produzir sentidos em diferentes contextos. (EM13LGG302) Compreender e posicionar-se criticamente diante de diversas visões de mundo presentes nos discursos em diferentes linguagens, levando em conta seus contextos de produção e de circulação. (EM13LGG303) Debater questões polêmicas de relevância social, analisando diferentes argumentos e opiniões manifestados, para negociar e sustentar posições, formular propostas, e intervir e tomar decisões democraticamente sustentadas, que levem em conta o bem comum e os Direitos Humanos, a consciência socioambiental e o consumo responsável em âmbito local, regional e global. (EM13LGG304) Mapear e criar, por meio de práticas de linguagem, possibilidades de atuação social, política, artís","localCatalogSourceId":"BNCC_EM_2018","localCatalogUrl":"https://basenacionalcomum.mec.gov.br/images/historico/BNCC_EnsinoMedio_embaixa_site_110518.pdf","localCatalogPage":61,"sourceCorrection":null,"sourceStage":"ENSINO_MEDIO","officialComponentCode":"LGG","officialSubjectArea":"LANGUAGES","candidateSubject":"LINGUAGENS","gradeRange":{"from":1,"to":3},"gradeCompatible":true,"proposalId":"V8_PROPOSAL_ENSINO_MEDIO_1_3_LGG_UNSPECIFIED_TEXT_LANGUAGE","proposalCanonicalCode":"LINGUAGENS_UNSPECIFIED_TEXT_LANGUAGE","proposalStatus":"NEW_SKILL_PENDING_REVIEW","gapClusterId":"V8_GAP_ENSINO_MEDIO_1_3_LGG_UNSPECIFIED_TEXT_LANGUAGE","referenceStatus":"OFFICIAL_SOURCE_IDENTIFIED_AND_EXCERPT_CHECKED","candidateStatus":"TECHNICAL_CANDIDATE_NOT_APPROVED_MAPPING","mappingClaim":"NONE","mappingStatus":"MAPPING_PENDING","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","internalSkillCode":"LANGUAGES_CREATE_COLLABORATIVELY_HS","internalGradeRange":{"from":1,"to":3},"evidenceSummary":"The authored capability is a bounded internal interpretation of EM13LGG301; it is not a promoted BNCC mapping.","observableCapability":"O estudante propõe uma escolha de linguagem vinculada ao público e objetivo, combina responsabilidades e revisa a produção com base em feedback fundamentado.","authoringLimitations":"A participação em processo real e a qualidade da colaboração precisam de observação docente; itens objetivos avaliam planejamento, não criação completa."},"official_mapping_status":"NOT_CLAIMED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING"}'::jsonb
  ) on conflict (catalog_id, code) do update
    set publication_status = 'STAGING'
    where existing.stage = 'ENSINO_MEDIO'
      and existing.grade_level = 1
      and existing.subject_area = 'LANGUAGES'
      and existing.domain = 'LINGUAGENS_MULTISSEMIOTICAS'
      and existing.active = false
      and existing.node_kind = 'LEAF'
      and existing.content_readiness = 'ADAPTIVE_READY'
      and existing.mastery_targetable = false
      and existing.parent_canonical_skill_id = v_parent_skill_id
      and existing.pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING'
      and existing.bncc_alignment_status = 'CANDIDATE'
      and existing.metadata->>'content_pack' in ('tec-escola-knowledge-expansion-v3', 'TECESCOLA_CORE_V5_QUESTION_FIRST')
      and existing.metadata->>'bncc_alignment' = 'NOT_CLAIMED'
      and existing.metadata->>'official_code' is null
      and (existing.metadata->>'official_mapping_status' = 'NOT_CLAIMED'
        or existing.metadata->>'mapping_status' = 'MAPPING_PENDING')
      and (
        (existing.metadata->>'content_pack' = 'tec-escola-knowledge-expansion-v3'
          and existing.metadata->>'staging_only' = 'true')
        or (existing.metadata->>'content_pack' = 'TECESCOLA_CORE_V5_QUESTION_FIRST'
          and existing.metadata->>'content_id' = 'v5-languages-collaboration'
          and existing.metadata->>'internal_skill_code' = 'LANGUAGES_CREATE_COLLABORATIVELY_HS')
      )
      and existing.publication_status in ('PUBLISHED', 'STAGING');
  if not exists (
    select 1 from public.learning_curriculum_skills
     where catalog_id = v_catalog_id and code = 'LANGUAGES_CREATE_COLLABORATIVELY_HS'
       and stage = 'ENSINO_MEDIO' and grade_level = 1
       and subject_area = 'LANGUAGES' and domain = 'LINGUAGENS_MULTISSEMIOTICAS'
       and parent_canonical_skill_id = v_parent_skill_id and active = false and mastery_targetable = false
       and pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING' and bncc_alignment_status = 'CANDIDATE'
       and publication_status = 'STAGING'
       and metadata->>'publication_status' = 'STAGING'
       and metadata->>'content_pack' in ('tec-escola-knowledge-expansion-v3', 'TECESCOLA_CORE_V5_QUESTION_FIRST')
  ) then raise exception 'V5_INTERNAL_SKILL_STAGING_SCOPE_CONFLICT:LANGUAGES_CREATE_COLLABORATIVELY_HS'; end if;

  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'LANGUAGES_CREATE_COLLABORATIVELY_HS';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Planejar junto, criar com propósito', 'Produção colaborativa requer objetivo comum, decisões negociadas, contribuições integradas, revisão fundamentada e respeito à autoria. Questões ajudam a praticar decisões; colaboração real exige observar o processo.', '## Comece por público e propósito
Antes de escolher vídeo, texto, cartaz, áudio ou apresentação, defina quem receberá a produção e o que precisa compreender ou fazer. Transforme o objetivo em critérios observáveis, como precisão das informações, legibilidade e coerência entre formatos. Uma escolha não é boa por ser popular ou visualmente atraente: precisa atender ao propósito sem criar barreiras desnecessárias.

## Organize o trabalho como um processo compartilhado
Liste etapas, dependências, prazos e decisões que precisam de integração. Papéis podem aproveitar interesses e conhecimentos, mas devem ser negociados e revistos. Compartilhe rascunhos cedo, combine quem pode editar cada parte e reserve momentos para integrar roteiro, imagem, fala, som e apresentação. Dividir tarefas sem rever como se conectam produz partes, não necessariamente uma criação coletiva.

## Dê e use feedback com critérios
Um comentário útil identifica um trecho ou efeito e o relaciona ao público e ao objetivo. “Não gostei” pode iniciar uma conversa; ainda é preciso perguntar o que ficou confuso, que evidência sustenta a leitura e que mudança poderia ser testada. Registre decisão e motivo. Divergência não exige que todas as sugestões sejam aplicadas, mas deve ser discutida com respeito e critérios comuns.

## Revise acesso, autoria e circulação
Teste legibilidade, contraste, legendas, descrição de imagens e clareza em cada suporte. Confirme fontes, condições de uso e autorização de pessoas identificáveis antes de publicar. O acesso a um arquivo não autoriza qualquer reutilização. Ao corrigir uma informação, confira todas as versões e planeje como substituir cópias que já circularam.

## Exemplo resolvido
Uma equipe cria áudio e cartaz para divulgar uma feira escolar. Primeiro confirma data, local e público; depois combina roteiro, revisão dos dados, gravação e diagramação. Uma pessoa que não participou do planejamento testa se encontra as informações essenciais em cada formato. O grupo corrige a data no áudio e no cartaz, registra a alteração e verifica autorização antes de usar uma fotografia de visitante. Esses registros mostram decisões e revisões, mas uma prova de múltipla escolha não comprova que o grupo colaborou; isso exige observar contribuições, integração e resposta ao feedback.

## Roteiro de colaboração
1. Defina público, propósito e critérios. 2. Liste etapas e dependências. 3. Negocie papéis e decisões. 4. Compartilhe protótipos. 5. Revise com evidências e feedback. 6. Teste acessibilidade, autoria e consistência antes da circulação.',
    'Para convidar famílias a uma feira, o grupo decide que a mensagem precisa informar data, local, horário e acessibilidade. Uma equipe prepara cartaz e áudio; colegas revisam a informação factual e outra pessoa testa cada peça separadamente. Ao perceber uma data divergente, o grupo corrige ambas, registra a versão substituída e confirma autorização para qualquer voz ou imagem. A qualidade do processo é avaliada por evidências de decisões, contribuições e revisão, não por um único acerto em uma questão.', array['Escreva público, propósito e critérios antes de escolher ferramentas.', 'Compartilhe rascunhos cedo e marque dependências entre as partes.', 'Peça feedback sobre um trecho e um critério, não apenas uma preferência.', 'Revise cada formato quanto a consistência, acessibilidade, autoria e autorização.', 'Registre decisões e limites; produto final não revela sozinho o processo.']::text[], 28, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-languages-collaboration","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Identificar público e objetivo de uma mensagem.","Distinguir opinião, evidência e decisão.","Respeitar autoria e privacidade em materiais compartilhados."],"key_concepts":["Colaboração combina propósito comum, negociação, contribuições integradas e revisão.","Papéis distribuem trabalho, mas não substituem comunicação nem responsabilidade compartilhada.","Feedback útil se refere a trecho e critério observáveis.","Cada modo e suporte pode exigir adaptação de acesso sem contradizer a mensagem.","Questões objetivas avaliam decisões de planejamento, não comprovam colaboração real."],"progression":[{"stage":"FOUNDATION","focus":"Relacionar público, propósito, critérios e organização inicial.","questionIds":["v5-lgg301-probe-01","v5-lgg301-probe-02","v5-lgg301-probe-03","v5-lgg301-practice-01","v5-lgg301-practice-02","v5-lgg301-practice-03"]},{"stage":"APPLICATION","focus":"Integrar papéis, formatos, feedback e revisão de protótipos.","questionIds":["v5-lgg301-practice-04","v5-lgg301-practice-05","v5-lgg301-practice-06","v5-lgg301-practice-07","v5-lgg301-practice-08"]},{"stage":"INTERMEDIATE","focus":"Resolver problemas de fluxo, dados, fontes e acessibilidade.","questionIds":["v5-lgg301-practice-09","v5-lgg301-practice-10","v5-lgg301-practice-11","v5-lgg301-transfer-01","v5-lgg301-transfer-02"]},{"stage":"ADVANCED_TRANSFER","focus":"Transferir critérios para contextos novos e negociar decisões complexas.","questionIds":["v5-lgg301-transfer-03","v5-lgg301-transfer-04","v5-lgg301-transfer-05","v5-lgg301-transfer-06","v5-lgg301-transfer-07","v5-lgg301-lock-01","v5-lgg301-lock-02","v5-lgg301-lock-03","v5-lgg301-lock-04","v5-lgg301-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar o processo em novos gêneros, públicos e situações de circulação.","questionIds":["v5-lgg301-review-01","v5-lgg301-review-02","v5-lgg301-review-03","v5-lgg301-review-04","v5-lgg301-review-05","v5-lgg301-review-06","v5-lgg301-review-07","v5-lgg301-review-08","v5-lgg301-review-09"]}],"micro_explanations":[{"trigger":"TOOL_BEFORE_PURPOSE","text":"Volte ao público e ao que ele precisa fazer. A ferramenta vem depois dessa decisão."},{"trigger":"ROLE_ISOLATION","text":"Dividir responsabilidades ajuda, mas combine dependências e revisão conjunta para integrar as partes."},{"trigger":"FEEDBACK_AS_PREFERENCE","text":"Peça um trecho, um efeito observado e o critério relacionado; preferência sozinha não define a revisão."},{"trigger":"ACCESS_AS_FEATURE","text":"Teste o material inteiro: legendas, posição, legibilidade e descrição podem interagir com a imagem."},{"trigger":"PROCESS_AS_PRODUCT","text":"Um produto pronto não mostra quem participou nem como decisões foram tomadas; procure registros de processo."}],"remediations":[{"misconception":"TOOL_BEFORE_PURPOSE","prompt":"Escreva: público ___; propósito ___; informação essencial ___. Só então compare formatos e explique qual atende melhor."},{"misconception":"ROLE_ISOLATION","prompt":"Desenhe as etapas e setas de dependência. Escolha dois pontos de integração e combine quem revisa cada um."},{"misconception":"FEEDBACK_AS_PREFERENCE","prompt":"Transforme “não gostei” em pergunta: que trecho, que efeito possível e que critério justificam testar uma mudança?"},{"misconception":"CONSENT_AS_MAJORITY","prompt":"Separe a decisão do grupo da autorização de cada pessoa para usar voz, imagem ou contribuição identificável."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Ensino Médio, Linguagens e suas Tecnologias","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["EM13LGG301 aborda processos de produção individual e colaborativa em diferentes linguagens e contextos."],"use":"Referência oficial para delimitação temática. O identificador interno continua sem alinhamento oficial aprovado; não se copia enunciado nem questão da fonte."},{"title":"Textos digitais multimodais de forma colaborativa entre os alunos","publisher":"Ministério da Educação, Caderno de Práticas","url":"https://basenacionalcomum.mec.gov.br/implementacao/praticas/caderno-de-praticas/ensino-fundamental-anos-finais/155-textos-digitais-multimodais-de-forma-colaborativa-entre-os-alunos","accessedOn":"2026-10-13","supports":["Exemplo institucional de produção multimodal colaborativa e integração de escrita e recursos digitais."],"use":"Referência contextual de prática; a atividade deste pacote é original e adequada ao Ensino Médio."}],"copyright_note":"Situações, questões, alternativas, feedback e rubrica são autorais. As fontes orientam escopo e desenho, sem copiar atividades. Mapeamento oficial e revisão pedagógica humana permanecem pendentes.","authentic_activities":[{"id":"lgg301-community-message-prototype","title":"Protótipo colaborativo para um público real da escola","objective":"Criar em grupo uma mensagem em dois formatos para um propósito escolar acordado e documentar decisões, integração e revisão.","context":"Escolham com a mediação docente um aviso ou convite de baixo risco que seja realmente útil à comunidade escolar.","materials":["Papel ou editor de texto","Dispositivo de gravação opcional","Lista de critérios acordada"],"instructions":"Definam público, propósito e informações essenciais. Negociem papéis e prazos; criem protótipos em dois formatos; troquem feedback baseado em critérios; revisem e registrem o motivo das mudanças. Não publiquem dados pessoais nem usem imagem, voz ou obra de terceiros sem autorização e verificação das condições de uso.","evidence":"Plano do grupo, versões ou registro de alterações, critérios, feedback recebido, justificativa de revisão e reflexão individual sobre contribuição. A qualidade da colaboração requer observação docente; não é inferida de um clique ou apenas do produto.","safety":"Use apenas informações não sensíveis e materiais seguros. A gravação é opcional; não há necessidade de publicar conteúdo fora da turma.","ageRange":"Ensino Médio, com adaptação e mediação docente conforme a turma.","mediation":"O professor ajuda a pactuar critérios, assegura oportunidade de participação e intervém em conflitos ou barreiras de acesso sem substituir as decisões do grupo.","privacyGuard":"Obter consentimento antes de registrar voz ou imagem; minimizar dados; manter arquivos no espaço autorizado pela escola e não publicar sem autorização específica.","rubric":[{"criterion":"Propósito e público","emerging":"O grupo ainda não explicita público ou ação esperada.","developing":"Define público e propósito, mas algumas escolhas não se conectam a eles.","proficient":"Explicita público e propósito e justifica escolhas de formato por critérios pertinentes."},{"criterion":"Integração e colaboração","emerging":"Partes e responsabilidades permanecem isoladas ou pouco registradas.","developing":"Há divisão de papéis e algum compartilhamento, mas poucas evidências de integração.","proficient":"O grupo negocia responsabilidades, integra contribuições e registra decisões conjuntas."},{"criterion":"Feedback e revisão","emerging":"Não há critério claro ou resposta documentada ao feedback.","developing":"O grupo considera comentários, mas justifica parcialmente as mudanças.","proficient":"Usa feedback específico, testa mudanças e registra evidências e limites da revisão."},{"criterion":"Acesso, autoria e cuidado","emerging":"Aspectos de acesso, privacidade ou autoria não foram verificados.","developing":"Verifica alguns aspectos, mas deixa pendências explícitas sem plano.","proficient":"Testa acessibilidade, confirma autoria e autorização e minimiza dados antes de circular."}]}],"objective":"Planejar uma produção colaborativa em diferentes linguagens, relacionando público, propósito, papéis, acessibilidade e critérios de revisão; distinguir evidência de processo de avaliação do produto.","common_mistake":"Achar que dividir tarefas, votar ou concluir um produto basta para provar colaboração; também é inadequado inferir participação, aprendizagem ou impacto sem observar dados correspondentes.","estimated_minutes":28}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'v5-languages-collaboration' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-lgg301-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"PLAN","contextFamily":"START_WITH_AUDIENCE","statement":"Uma turma prepara uma mensagem para orientar visitantes na feira escolar. Qual decisão ajuda a escolher formato e linguagem antes de dividir tarefas?","options":["Definir o que os visitantes precisam saber e fazer.","Escolher primeiro o aplicativo favorito de cada integrante.","Produzir peças separadas sem combinar a mensagem.","Contar quantas cores o grupo consegue usar."],"correctAnswer":"Definir o que os visitantes precisam saber e fazer.","explanation":"Público e propósito orientam formato, conteúdo e critérios de sucesso.","hint":"Complete: quem recebe a mensagem e o que precisa compreender?","errorFocus":"Começar pelo recurso sem propósito","misconceptions":{"Escolher primeiro o aplicativo favorito de cada integrante.":["TOOL_BEFORE_PURPOSE"],"Produzir peças separadas sem combinar a mensagem.":["UNINTEGRATED_PARTS"],"Contar quantas cores o grupo consegue usar.":["DECORATION_AS_GOAL"]},"authoringOrder":1,"position":1},{"id":"v5-lgg301-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"ORGANIZE","contextFamily":"ROLE_DEPENDENCIES","statement":"Em um projeto de podcast com roteiro, gravação e edição, que acordo reduz o risco de as partes não se encaixarem?","options":["Deixar cada pessoa escolher o tema da própria parte.","Combinar entregas, prazos e um momento de revisão conjunta.","Esperar a edição terminar para só então compartilhar o roteiro.","Usar o mesmo tempo de fala para todos, mesmo sem relação com o objetivo."],"correctAnswer":"Combinar entregas, prazos e um momento de revisão conjunta.","explanation":"Papéis distintos precisam de pontos de integração e critérios compartilhados.","hint":"O que precisa ser revisto antes da gravação final?","errorFocus":"Confundir divisão de tarefas com colaboração","misconceptions":{"Deixar cada pessoa escolher o tema da própria parte.":["ROLE_ISOLATION"],"Esperar a edição terminar para só então compartilhar o roteiro.":["LATE_INTEGRATION"],"Usar o mesmo tempo de fala para todos, mesmo sem relação com o objetivo.":["EQUAL_TIME_AS_QUALITY"]},"authoringOrder":2,"position":2},{"id":"v5-lgg301-probe-03","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"CONSENT_AND_CREDITS","statement":"Uma equipe quer incluir a fotografia de uma pessoa da comunidade em um mural digital. Qual procedimento é adequado antes da publicação?","options":["Publicar porque a fotografia foi enviada ao grupo.","Retirar o nome da pessoa para dispensar autorização.","Obter autorização para o uso pretendido e registrar autoria conforme combinado.","Pedir autorização apenas se alguém reclamar depois."],"correctAnswer":"Obter autorização para o uso pretendido e registrar autoria conforme combinado.","explanation":"Receber ou conseguir acessar um arquivo não equivale a consentimento para qualquer uso.","hint":"Pense no controle da pessoa retratada e nas condições de circulação.","errorFocus":"Tratar acesso ao arquivo como autorização","misconceptions":{"Publicar porque a fotografia foi enviada ao grupo.":["FILE_ACCESS_AS_PERMISSION"],"Retirar o nome da pessoa para dispensar autorização.":["ANONYMITY_AS_CONSENT"],"Pedir autorização apenas se alguém reclamar depois.":["RETROACTIVE_PERMISSION"]},"authoringOrder":3,"position":3},{"id":"v5-lgg301-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"PLAN","contextFamily":"SUCCESS_CRITERIA","statement":"O grupo vai criar um cartaz e um áudio curto para divulgar uma campanha de doação de livros. Qual critério permite avaliar se as duas peças cumprem o objetivo?","options":["Avaliar apenas se as duas peças usam a mesma cor.","Contar curtidas antes de conferir as informações.","Exigir que cartaz e áudio tenham exatamente o mesmo texto.","Verificar se informam com clareza o público, o que pode ser doado, o local e o prazo."],"correctAnswer":"Verificar se informam com clareza o público, o que pode ser doado, o local e o prazo.","explanation":"Critérios de sucesso devem corresponder às informações e ações que o público precisa realizar.","hint":"Liste a informação necessária para alguém participar.","errorFocus":"Usar semelhança visual como único critério","misconceptions":{"Avaliar apenas se as duas peças usam a mesma cor.":["COLOR_AS_SUCCESS"],"Contar curtidas antes de conferir as informações.":["LIKES_AS_ACCURACY"],"Exigir que cartaz e áudio tenham exatamente o mesmo texto.":["IDENTICAL_WORDING_REQUIRED"]},"authoringOrder":4,"position":1},{"id":"v5-lgg301-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"ORGANIZE","contextFamily":"ROLE_STRENGTHS","statement":"Uma integrante prefere revisar textos e outro tem experiência com edição de áudio. Como distribuir os papéis de forma colaborativa?","options":["Considerar interesses e necessidades do projeto, negociar responsabilidades e permitir revisão cruzada.","Fixar os mesmos papéis em todos os projetos, sem conversa.","Deixar uma pessoa decidir tudo porque tem mais experiência.","Distribuir tarefas aleatoriamente e não revisá-las."],"correctAnswer":"Considerar interesses e necessidades do projeto, negociar responsabilidades e permitir revisão cruzada.","explanation":"A distribuição pode aproveitar conhecimentos, mas decisões e responsabilidade continuam compartilhadas.","hint":"Que acordo combina contribuição individual e responsabilidade do grupo?","errorFocus":"Confundir experiência com poder exclusivo","misconceptions":{"Fixar os mesmos papéis em todos os projetos, sem conversa.":["FIXED_ROLES"],"Deixar uma pessoa decidir tudo porque tem mais experiência.":["EXPERT_CONTROL"],"Distribuir tarefas aleatoriamente e não revisá-las.":["RANDOM_NO_REVIEW"]},"authoringOrder":5,"position":2},{"id":"v5-lgg301-practice-03","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CREATE","contextFamily":"STORYBOARD_SEQUENCE","statement":"Um vídeo tutorial mostra materiais, montagem e resultado final. Que recurso ajuda a equipe a planejar a ordem antes de gravar?","options":["Uma lista de efeitos escolhidos sem relação com as etapas.","Um roteiro visual ou storyboard com cenas e informações essenciais.","A gravação completa sem combinar sequência.","Um cartaz final usado como substituto de todas as cenas."],"correctAnswer":"Um roteiro visual ou storyboard com cenas e informações essenciais.","explanation":"Um storyboard torna a sequência visível e permite revisar lacunas antes da produção.","hint":"Qual representação permite antever a ordem das cenas?","errorFocus":"Confundir acabamento com planejamento","misconceptions":{"Uma lista de efeitos escolhidos sem relação com as etapas.":["EFFECTS_BEFORE_SEQUENCE"],"A gravação completa sem combinar sequência.":["RECORD_WITHOUT_PLAN"],"Um cartaz final usado como substituto de todas as cenas.":["POSTER_AS_VIDEO"]},"authoringOrder":6,"position":3},{"id":"v5-lgg301-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"REVISE","contextFamily":"ACTIONABLE_FEEDBACK","statement":"Uma colega comenta “o começo não me ajudou a entender o tema”. Qual resposta transforma o comentário em feedback utilizável?","options":["Responder que o começo está bom porque o grupo gostou.","Apagar a fala de quem escreveu sem explicar o motivo.","Perguntar qual informação faltou e apontar uma parte do roteiro que pode ser esclarecida.","Mudar todas as cenas para evitar qualquer crítica."],"correctAnswer":"Perguntar qual informação faltou e apontar uma parte do roteiro que pode ser esclarecida.","explanation":"Feedback específico liga uma observação a um critério e sugere um próximo passo verificável.","hint":"Peça um exemplo concreto e relacione-o ao propósito da abertura.","errorFocus":"Tratar preferência como critério suficiente","misconceptions":{"Responder que o começo está bom porque o grupo gostou.":["DEFENSIVE_FEEDBACK"],"Apagar a fala de quem escreveu sem explicar o motivo.":["UNEXPLAINED_DELETION"],"Mudar todas as cenas para evitar qualquer crítica.":["TOTAL_REVISION_FROM_ONE_COMMENT"]},"authoringOrder":7,"position":4},{"id":"v5-lgg301-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CREATE","contextFamily":"ACCESSIBLE_CAPTIONS","statement":"Uma entrevista será publicada como vídeo e também precisa ser compreensível sem áudio. O que a equipe deve planejar?","options":["Aumentar o volume e dispensar qualquer alternativa textual.","Colocar toda a fala em letras pequenas sobre a imagem.","Adicionar música para substituir as falas.","Legendas revisadas, identificação de falantes quando necessária e descrição de sons relevantes."],"correctAnswer":"Legendas revisadas, identificação de falantes quando necessária e descrição de sons relevantes.","explanation":"Legendas e indicações pertinentes ampliam acesso; precisam ser legíveis e fiéis ao conteúdo.","hint":"Considere quem não ouve a faixa sonora e como acompanhará turnos e sons.","errorFocus":"Confundir volume com acessibilidade","misconceptions":{"Aumentar o volume e dispensar qualquer alternativa textual.":["VOLUME_AS_ACCESS"],"Colocar toda a fala em letras pequenas sobre a imagem.":["UNREADABLE_CAPTIONS"],"Adicionar música para substituir as falas.":["MUSIC_AS_TRANSCRIPT"]},"authoringOrder":8,"position":5},{"id":"v5-lgg301-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ORGANIZE","contextFamily":"SHARED_DECISION_RULE","statement":"Dois integrantes discordam sobre qual imagem representa melhor a campanha. Qual procedimento torna a decisão justificável?","options":["Comparar as imagens com o público, o propósito e critérios acordados, ouvindo as razões de cada pessoa.","Escolher a imagem de quem fala mais alto.","Votar sem conhecer os critérios e encerrar a conversa.","Usar as duas imagens mesmo que se contradigam."],"correctAnswer":"Comparar as imagens com o público, o propósito e critérios acordados, ouvindo as razões de cada pessoa.","explanation":"Critérios prévios permitem explicar a escolha e considerar contribuições diferentes.","hint":"Qual evidência mostraria que a imagem ajuda a mensagem?","errorFocus":"Trocar justificativa por autoridade ou volume","misconceptions":{"Escolher a imagem de quem fala mais alto.":["LOUDNESS_AS_AUTHORITY"],"Votar sem conhecer os critérios e encerrar a conversa.":["VOTE_WITHOUT_CRITERIA"],"Usar as duas imagens mesmo que se contradigam.":["CONTRADICTION_UNREVIEWED"]},"authoringOrder":9,"position":6},{"id":"v5-lgg301-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"REVISE","contextFamily":"VERSION_HISTORY","statement":"Após testar um protótipo, o grupo altera o título e a ordem das informações. Que registro ajuda a compreender a revisão?","options":["Guardar somente a versão final e apagar todo o processo.","Anotar a mudança, o comentário que a motivou e o critério que ela busca melhorar.","Registrar apenas quem teve a ideia, sem explicar a decisão.","Fazer mudanças sem informar às pessoas responsáveis pelas outras partes."],"correctAnswer":"Anotar a mudança, o comentário que a motivou e o critério que ela busca melhorar.","explanation":"O histórico relaciona evidência, decisão e efeito pretendido sem reduzir o processo à autoria individual.","hint":"Que informação permitirá entender por que o protótipo mudou?","errorFocus":"Apagar evidências do processo de revisão","misconceptions":{"Guardar somente a versão final e apagar todo o processo.":["FINAL_ONLY"],"Registrar apenas quem teve a ideia, sem explicar a decisão.":["AUTHOR_ONLY"],"Fazer mudanças sem informar às pessoas responsáveis pelas outras partes.":["UNSHARED_CHANGE"]},"authoringOrder":10,"position":7},{"id":"v5-lgg301-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"MODE_COMPLEMENT","statement":"Um folheto explica como chegar a um evento e inclui um mapa simples. Qual pergunta ajuda a avaliar a integração entre texto e imagem?","options":["O mapa comprova que todos encontrarão o local?","As palavras e o mapa precisam repetir cada detalhe?","O mapa acrescenta orientação espacial que complementa as instruções verbais?","A imagem pode ser avaliada sem considerar o percurso descrito?"],"correctAnswer":"O mapa acrescenta orientação espacial que complementa as instruções verbais?","explanation":"A relação entre modos deve ser verificada pelo que cada parte acrescenta ao propósito.","hint":"Compare a informação espacial da imagem com as etapas escritas.","errorFocus":"Assumir que modos integrados provam o resultado externo","misconceptions":{"O mapa comprova que todos encontrarão o local?":["TEXT_IMAGE_AS_OUTCOME"],"As palavras e o mapa precisam repetir cada detalhe?":["REDUNDANCY_REQUIRED"],"A imagem pode ser avaliada sem considerar o percurso descrito?":["IMAGE_WITHOUT_CONTEXT"]},"authoringOrder":11,"position":8},{"id":"v5-lgg301-practice-09","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SOURCE_ATTRIBUTION","statement":"A equipe usa um trecho de música de outra autoria em um vídeo escolar. O que precisa ser verificado antes de publicar?","options":["Se o trecho é curto, pois qualquer trecho curto pode ser usado livremente.","Se a música está disponível online, pois isso a torna livre de direitos.","Se o grupo consegue ocultar a fonte no arquivo final.","Se o uso é permitido nas condições previstas e como atribuir a autoria de modo adequado."],"correctAnswer":"Se o uso é permitido nas condições previstas e como atribuir a autoria de modo adequado.","explanation":"Disponibilidade e duração, isoladamente, não determinam permissão; a equipe deve verificar licença e contexto de uso.","hint":"Procure as condições explícitas de uso e atribuição da obra.","errorFocus":"Confundir disponibilidade pública com licença","misconceptions":{"Se o trecho é curto, pois qualquer trecho curto pode ser usado livremente.":["SHORT_MEANS_FREE"],"Se a música está disponível online, pois isso a torna livre de direitos.":["ONLINE_MEANS_FREE"],"Se o grupo consegue ocultar a fonte no arquivo final.":["HIDE_SOURCE"]},"authoringOrder":12,"position":9},{"id":"v5-lgg301-practice-10","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"PLAN","contextFamily":"DEPENDENCY_MAP","statement":"Um projeto terá cartaz impresso e postagem digital, mas ambos dependem da confirmação do local. Que plano reduz retrabalho?","options":["Marcar a confirmação como dependência e só fechar as peças depois de validar o local.","Finalizar os dois formatos com locais presumidos.","Publicar primeiro e corrigir se houver erro.","Retirar o local de todas as peças sem consultar o público."],"correctAnswer":"Marcar a confirmação como dependência e só fechar as peças depois de validar o local.","explanation":"Mapear dependências evita propagar um dado incerto por diferentes formatos.","hint":"Qual informação ainda precisa de validação antes da versão final?","errorFocus":"Tratar dado pendente como confirmado","misconceptions":{"Finalizar os dois formatos com locais presumidos.":["ASSUMED_LOCATION"],"Publicar primeiro e corrigir se houver erro.":["PUBLISH_THEN_FIX"],"Retirar o local de todas as peças sem consultar o público.":["OMIT_WITHOUT_DECISION"]},"authoringOrder":13,"position":10},{"id":"v5-lgg301-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"REFLECT","contextFamily":"PROCESS_REFLECTION","statement":"Ao final do projeto, qual evidência permite avaliar melhor a colaboração, além do produto pronto?","options":["Apenas o número de arquivos produzidos.","Registros das decisões, das contribuições, do feedback recebido e das revisões realizadas.","A opinião de uma pessoa sobre quem trabalhou mais.","A nota final sem critérios ou observações do processo."],"correctAnswer":"Registros das decisões, das contribuições, do feedback recebido e das revisões realizadas.","explanation":"A colaboração requer evidências do processo e critérios claros; o produto isolado não mostra como foi criado.","hint":"Que registros mostram decisões compartilhadas e resposta a feedback?","errorFocus":"Inferir o processo somente pelo produto","misconceptions":{"Apenas o número de arquivos produzidos.":["FILE_COUNT_AS_COLLABORATION"],"A opinião de uma pessoa sobre quem trabalhou mais.":["UNSUPPORTED_PERSONAL_JUDGMENT"],"A nota final sem critérios ou observações do processo.":["SCORE_WITHOUT_CRITERIA"]},"authoringOrder":14,"position":11},{"id":"v5-lgg301-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"SCIENCE_FAIR_INVITATION","statement":"Uma equipe divulga uma feira de ciências a famílias por áudio e por cartaz. Como verificar se os formatos se complementam sem pressupor que todos receberão ambos?","options":["Deixar data apenas no áudio porque o cartaz tem imagem.","Usar mensagens diferentes para atrair mais pessoas.","Conferir se cada formato comunica sozinho as informações essenciais e se juntos mantêm a mesma data e local.","Contar que cada família verá os dois materiais."],"correctAnswer":"Conferir se cada formato comunica sozinho as informações essenciais e se juntos mantêm a mesma data e local.","explanation":"Cada canal precisa sustentar a ação principal, e a consistência entre versões evita contradições.","hint":"Imagine uma pessoa que recebeu apenas um dos materiais.","errorFocus":"Depender de exposição a todos os canais","misconceptions":{"Deixar data apenas no áudio porque o cartaz tem imagem.":["MISSING_CORE_INFO"],"Usar mensagens diferentes para atrair mais pessoas.":["INCONSISTENT_MESSAGE"],"Contar que cada família verá os dois materiais.":["ASSUMED_EXPOSURE"]},"authoringOrder":15,"position":1},{"id":"v5-lgg301-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"COMMUNITY_ORAL_HISTORY","statement":"Um grupo grava relatos voluntários sobre a história do bairro e prepara uma exposição. Qual prática respeita participantes e melhora a confiabilidade do trabalho?","options":["Editar as falas para que todas sustentem uma narrativa única.","Publicar os relatos completos porque a participação foi voluntária.","Retirar divergências sem registrar que houve versões diferentes.","Combinar consentimento e uso, identificar quando uma informação é relato e revisar nomes e datas com fontes adequadas."],"correctAnswer":"Combinar consentimento e uso, identificar quando uma informação é relato e revisar nomes e datas com fontes adequadas.","explanation":"Consentimento, fidelidade e checagem distinguem memória oral de afirmações verificadas sem apagar perspectivas.","hint":"Separe autorização, edição e confirmação factual: são decisões relacionadas, mas distintas.","errorFocus":"Confundir participação voluntária com autorização irrestrita","misconceptions":{"Editar as falas para que todas sustentem uma narrativa única.":["UNIFIED_NARRATIVE"],"Publicar os relatos completos porque a participação foi voluntária.":["VOLUNTEER_AS_BLANKET_PERMISSION"],"Retirar divergências sem registrar que houve versões diferentes.":["ERASE_DIVERGENCE"]},"authoringOrder":16,"position":2},{"id":"v5-lgg301-transfer-03","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"CREATE","contextFamily":"SCHOOL_WASTE_CAMPAIGN","statement":"Uma campanha sobre separação de resíduos terá infográfico e fala de apresentação. Qual plano ajuda a manter a informação consistente?","options":["Definir fonte e termos comuns, atribuir revisão dos dados e conferir os dois formatos com a mesma lista de critérios.","Permitir que cada integrante escolha dados diferentes para seu formato.","Copiar o infográfico para a fala sem adaptar a explicação.","Finalizar cada peça sem compartilhar rascunhos."],"correctAnswer":"Definir fonte e termos comuns, atribuir revisão dos dados e conferir os dois formatos com a mesma lista de critérios.","explanation":"Um núcleo comum de evidências preserva consistência, enquanto cada modo pode organizar a explicação de forma própria.","hint":"Como o grupo detectará divergências de dado antes de apresentar?","errorFocus":"Confundir consistência com cópia literal","misconceptions":{"Permitir que cada integrante escolha dados diferentes para seu formato.":["DATA_DRIFT"],"Copiar o infográfico para a fala sem adaptar a explicação.":["COPY_WITHOUT_ADAPTATION"],"Finalizar cada peça sem compartilhar rascunhos.":["SEPARATE_FINALIZATION"]},"authoringOrder":17,"position":3},{"id":"v5-lgg301-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"MULTILINGUAL_WELCOME","statement":"Uma escola prepara uma mensagem de acolhimento para famílias que usam diferentes línguas. Que revisão é mais adequada?","options":["Usar tradução automática sem revisão porque o sentido será sempre equivalente.","Consultar usuários voluntários, verificar a precisão das versões e oferecer informação acessível sem tratar uma língua como defeito.","Eliminar exemplos culturais para que todas as famílias recebam exatamente a mesma leitura.","Pedir que as famílias aprendam a versão única antes de participar."],"correctAnswer":"Consultar usuários voluntários, verificar a precisão das versões e oferecer informação acessível sem tratar uma língua como defeito.","explanation":"Revisão com usuários pode revelar ambiguidades; equivalência e acesso precisam ser avaliados no contexto.","hint":"Quem pode verificar se cada versão comunica a mesma ação com clareza?","errorFocus":"Supor equivalência automática entre línguas","misconceptions":{"Usar tradução automática sem revisão porque o sentido será sempre equivalente.":["MACHINE_TRANSLATION_AS_GUARANTEE"],"Eliminar exemplos culturais para que todas as famílias recebam exatamente a mesma leitura.":["CULTURE_ERASURE"],"Pedir que as famílias aprendam a versão única antes de participar.":["ACCESS_AS_USER_BURDEN"]},"authoringOrder":18,"position":4},{"id":"v5-lgg301-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"REVISE","contextFamily":"PUBLIC_SERVICE_AUDIO","statement":"Uma gravação sobre horário de atendimento contém uma data falada incorretamente, embora o cartaz esteja correto. Qual ação é melhor?","options":["Manter o áudio porque o cartaz tem o dado certo.","Apagar o cartaz para evitar comparação.","Corrigir o áudio, conferir a informação em ambos os formatos e registrar qual versão substitui a anterior.","Esperar que ouvintes identifiquem o erro por conta própria."],"correctAnswer":"Corrigir o áudio, conferir a informação em ambos os formatos e registrar qual versão substitui a anterior.","explanation":"A informação essencial deve ser consistente em todos os formatos e versões publicadas.","hint":"O que alguém que recebeu somente o áudio entenderá?","errorFocus":"Tratar divergência entre formatos como irrelevante","misconceptions":{"Manter o áudio porque o cartaz tem o dado certo.":["CHANNEL_EXCUSE"],"Apagar o cartaz para evitar comparação.":["DELETE_CORRECT_VERSION"],"Esperar que ouvintes identifiquem o erro por conta própria.":["USER_MUST_CATCH_ERROR"]},"authoringOrder":19,"position":5},{"id":"v5-lgg301-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"PLAN","contextFamily":"LOCAL_ACCESSIBILITY_MAP","statement":"Um mapa colaborativo indica rampas em espaços públicos. Como a equipe deve apresentar pontos ainda não verificados?","options":["Marcar todos os pontos como acessíveis para completar o mapa.","Omitir a data para que a informação pareça permanente.","Publicar contribuições identificáveis sem autorização.","Diferenciar locais confirmados e pendentes, informar data e método da verificação e convidar correções com cuidado."],"correctAnswer":"Diferenciar locais confirmados e pendentes, informar data e método da verificação e convidar correções com cuidado.","explanation":"Transparência sobre método, data e incerteza evita prometer acessibilidade não verificada.","hint":"Como leitores distinguirão observação confirmada de informação pendente?","errorFocus":"Apresentar dado incompleto como certeza","misconceptions":{"Marcar todos os pontos como acessíveis para completar o mapa.":["FALSE_COMPLETENESS"],"Omitir a data para que a informação pareça permanente.":["HIDE_STALENESS"],"Publicar contribuições identificáveis sem autorização.":["IDENTIFIABLE_DATA_WITHOUT_CONSENT"]},"authoringOrder":20,"position":6},{"id":"v5-lgg301-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PEER_REVIEW_CONFLICT","statement":"Duas pessoas dão sugestões incompatíveis para uma peça. Qual encaminhamento preserva diálogo e propósito?","options":["Comparar cada sugestão com os critérios, testar uma versão quando possível e registrar a decisão e seus limites.","Aplicar as duas sugestões mesmo que a mensagem fique incoerente.","Escolher a proposta da pessoa com maior cargo no grupo.","Ignorar as duas para evitar conversa difícil."],"correctAnswer":"Comparar cada sugestão com os critérios, testar uma versão quando possível e registrar a decisão e seus limites.","explanation":"Critérios comuns permitem testar alternativas sem reduzir a decisão a hierarquia ou evitar desacordo.","hint":"Que evidência do público ou do objetivo ajudaria a comparar as opções?","errorFocus":"Resolver conflito por hierarquia ou evasão","misconceptions":{"Aplicar as duas sugestões mesmo que a mensagem fique incoerente.":["INCOHERENT_MERGE"],"Escolher a proposta da pessoa com maior cargo no grupo.":["STATUS_AS_EVIDENCE"],"Ignorar as duas para evitar conversa difícil.":["AVOID_DISCUSSION"]},"authoringOrder":21,"position":7},{"id":"v5-lgg301-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REPRESENTATION_CHOICE","statement":"Um material apresenta uma comunidade apenas por uma imagem estereotipada encontrada em uma busca rápida. Qual revisão é mais responsável?","options":["Manter a imagem porque combina com o título.","Rever contexto e representação com fontes e vozes pertinentes, consultar participantes quando apropriado e reconsiderar a escolha.","Trocar por outra imagem genérica sem verificar autoria ou contexto.","Adicionar uma frase positiva e manter o restante igual."],"correctAnswer":"Rever contexto e representação com fontes e vozes pertinentes, consultar participantes quando apropriado e reconsiderar a escolha.","explanation":"Representação exige contexto e revisão, não apenas intenção positiva ou correspondência superficial.","hint":"Que perspectiva está ausente e que evidência pode orientar a revisão?","errorFocus":"Supor que intenção positiva elimina estereótipos","misconceptions":{"Manter a imagem porque combina com o título.":["TITLE_MATCH_AS_VALIDATION"],"Trocar por outra imagem genérica sem verificar autoria ou contexto.":["GENERIC_REPLACEMENT"],"Adicionar uma frase positiva e manter o restante igual.":["POSITIVE_CAPTION_AS_FIX"]},"authoringOrder":22,"position":1},{"id":"v5-lgg301-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"REVISE","contextFamily":"ACCESSIBILITY_TRADEOFF","statement":"O vídeo tem legendas, mas elas cobrem informações importantes que aparecem na parte inferior da imagem. O que a equipe deve fazer?","options":["Manter as legendas porque qualquer legenda já garante acesso.","Remover todas as informações visuais.","Ajustar posição e sincronização, testar legibilidade e verificar se texto e imagem continuam compreensíveis.","Reduzir muito a fonte para não cobrir a cena."],"correctAnswer":"Ajustar posição e sincronização, testar legibilidade e verificar se texto e imagem continuam compreensíveis.","explanation":"Acessibilidade precisa ser testada na composição completa; uma solução pode criar outra barreira.","hint":"Observe se uma pessoa consegue acompanhar fala e informação visual ao mesmo tempo.","errorFocus":"Tratar presença de recurso como garantia de acesso","misconceptions":{"Manter as legendas porque qualquer legenda já garante acesso.":["FEATURE_PRESENT_AS_ACCESS"],"Remover todas as informações visuais.":["VISUAL_ERASURE"],"Reduzir muito a fonte para não cobrir a cena.":["TINY_TEXT_FIX"]},"authoringOrder":23,"position":2},{"id":"v5-lgg301-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"SAMPLE_FEEDBACK_LIMIT","statement":"Três colegas dizem que entenderam a mensagem. Qual conclusão a equipe pode registrar com rigor?","options":["Todas as pessoas entenderão a mensagem.","O material não precisa de revisão adicional.","A mensagem causou a ação desejada.","As três pessoas consultadas relataram compreensão; isso é um indício limitado, não prova sobre todo o público."],"correctAnswer":"As três pessoas consultadas relataram compreensão; isso é um indício limitado, não prova sobre todo o público.","explanation":"O registro deve corresponder à amostra observada e não extrapolar para audiência ou comportamento.","hint":"Especifique quem foi consultado e o que foi perguntado.","errorFocus":"Generalizar além das evidências coletadas","misconceptions":{"Todas as pessoas entenderão a mensagem.":["SMALL_SAMPLE_UNIVERSALIZED"],"O material não precisa de revisão adicional.":["NO_MORE_REVIEW"],"A mensagem causou a ação desejada.":["COMPREHENSION_AS_BEHAVIOR"]},"authoringOrder":24,"position":3},{"id":"v5-lgg301-lock-04","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"PLAN","contextFamily":"DISAGREEMENT_PROTOCOL","statement":"No grupo, uma integrante não concorda com a edição de sua fala. Qual procedimento combina colaboração e respeito à autoria?","options":["Conversar sobre o objetivo da edição, rever o trecho com a integrante e definir juntos o uso autorizado.","Publicar porque o grupo aprovou a edição por maioria.","Retirar o nome da integrante e manter a fala.","Manter o trecho e pedir desculpas depois."],"correctAnswer":"Conversar sobre o objetivo da edição, rever o trecho com a integrante e definir juntos o uso autorizado.","explanation":"Decisão coletiva não elimina consentimento nem acordos sobre contribuição identificável.","hint":"Distingua votação do grupo de autorização para usar a contribuição de alguém.","errorFocus":"Usar maioria para substituir consentimento","misconceptions":{"Publicar porque o grupo aprovou a edição por maioria.":["MAJORITY_AS_CONSENT"],"Retirar o nome da integrante e manter a fala.":["ANONYMITY_AS_PERMISSION"],"Manter o trecho e pedir desculpas depois.":["APOLOGY_AFTER_PUBLICATION"]},"authoringOrder":25,"position":4},{"id":"v5-lgg301-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REVISION_CAUSALITY","statement":"Após uma mudança no cartaz, mais pessoas compareceram ao evento. O grupo pode afirmar que a mudança causou o aumento?","options":["Sim, pois a ordem temporal comprova causa.","Não sem comparar explicações e dados adequados; a mudança ocorreu junto ao aumento, mas isso não estabelece causa.","Sim, se o cartaz recebeu comentários positivos.","Não, porque materiais de divulgação nunca influenciam participação."],"correctAnswer":"Não sem comparar explicações e dados adequados; a mudança ocorreu junto ao aumento, mas isso não estabelece causa.","explanation":"Um resultado posterior pode ter outras explicações; é necessário desenho de avaliação para atribuir causalidade.","hint":"Que outras mudanças ou fatores podem explicar o comparecimento?","errorFocus":"Confundir sequência temporal com causalidade","misconceptions":{"Sim, pois a ordem temporal comprova causa.":["AFTER_THEREFORE_BECAUSE"],"Sim, se o cartaz recebeu comentários positivos.":["PRAISE_AS_CAUSAL_EVIDENCE"],"Não, porque materiais de divulgação nunca influenciam participação.":["NEVER_EFFECT_CLAIM"]},"authoringOrder":26,"position":5},{"id":"v5-lgg301-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"PLAN","contextFamily":"REVIEW_POPUP_EXHIBIT","statement":"Uma exposição itinerante terá versão impressa e digital. Qual revisão inicial reduz falhas entre as duas?","options":["Verificar apenas se os arquivos abrem.","Usar a mesma dimensão de letra em papel e celular.","Conferir objetivo, informação essencial, público, legibilidade e consistência em cada formato.","Escolher um formato e descartar o outro sem consulta."],"correctAnswer":"Conferir objetivo, informação essencial, público, legibilidade e consistência em cada formato.","explanation":"A revisão considera finalidade e condições específicas de circulação de cada suporte.","hint":"Teste a experiência em cada meio, não apenas o arquivo.","errorFocus":"Confundir arquivo funcional com comunicação eficaz","misconceptions":{"Verificar apenas se os arquivos abrem.":["FILE_OPENS_AS_SUCCESS"],"Usar a mesma dimensão de letra em papel e celular.":["SAME_SIZE_EVERYWHERE"],"Escolher um formato e descartar o outro sem consulta.":["FORMAT_REMOVED_WITHOUT_REASON"]},"authoringOrder":27,"position":1},{"id":"v5-lgg301-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ORGANIZE","contextFamily":"REVIEW_HANDOFF","statement":"Uma pessoa termina sua parte antes das demais. O que mantém a colaboração sem duplicar trabalho?","options":["Editar as partes das outras pessoas sem avisar.","Esperar em silêncio até o prazo final.","Publicar sua própria parte para pressionar o grupo.","Compartilhar o rascunho, verificar dependências e oferecer revisão acordada ao grupo."],"correctAnswer":"Compartilhar o rascunho, verificar dependências e oferecer revisão acordada ao grupo.","explanation":"Transparência sobre andamento permite ajuda coordenada sem retirar autoria ou controle dos demais.","hint":"Qual ação ajuda o conjunto e preserva os acordos de papel?","errorFocus":"Confundir iniciativa com controle unilateral","misconceptions":{"Editar as partes das outras pessoas sem avisar.":["UNANNOUNCED_EDIT"],"Esperar em silêncio até o prazo final.":["SILENT_WAIT"],"Publicar sua própria parte para pressionar o grupo.":["PUBLIC_PRESSURE"]},"authoringOrder":28,"position":2},{"id":"v5-lgg301-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"REVIEW_ALT_TEXT","statement":"Um infográfico digital mostra uma comparação que não aparece no texto alternativo. O que precisa ser revisto?","options":["Incluir no texto alternativo a informação essencial da comparação, sem repetir decoração irrelevante.","Adicionar somente “imagem de gráfico”.","Repetir cada cor sem explicar as relações de dados.","Remover o gráfico e deixar a conclusão sem evidência."],"correctAnswer":"Incluir no texto alternativo a informação essencial da comparação, sem repetir decoração irrelevante.","explanation":"Uma descrição funcional comunica relações relevantes para quem não acessa o visual.","hint":"Que conclusão sustentada pelo gráfico precisa estar disponível em texto?","errorFocus":"Confundir nomeação da imagem com descrição útil","misconceptions":{"Adicionar somente “imagem de gráfico”.":["GENERIC_ALT_TEXT"],"Repetir cada cor sem explicar as relações de dados.":["COLOR_LIST_ONLY"],"Remover o gráfico e deixar a conclusão sem evidência.":["CONCLUSION_WITHOUT_EVIDENCE"]},"authoringOrder":29,"position":3},{"id":"v5-lgg301-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"REVISE","contextFamily":"REVIEW_READING_LEVEL","statement":"Uma mensagem de serviço usa termos técnicos que o público consultado não compreendeu. Qual revisão é melhor?","options":["Retirar os detalhes necessários para simplificar a qualquer custo.","Substituir ou explicar termos mantendo precisão e testar novamente com representantes do público.","Manter o texto e concluir que o público deve pesquisar.","Adicionar mais termos técnicos para parecer preciso."],"correctAnswer":"Substituir ou explicar termos mantendo precisão e testar novamente com representantes do público.","explanation":"Linguagem simples busca compreensão sem sacrificar a exatidão; o teste verifica a revisão.","hint":"Qual termo é necessário e como pode ser explicado com precisão?","errorFocus":"Confundir simplificação com perda de precisão","misconceptions":{"Retirar os detalhes necessários para simplificar a qualquer custo.":["DELETE_NECESSARY_DETAIL"],"Manter o texto e concluir que o público deve pesquisar.":["BURDEN_THE_READER"],"Adicionar mais termos técnicos para parecer preciso.":["JARGON_AS_PRECISION"]},"authoringOrder":30,"position":4},{"id":"v5-lgg301-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"REVIEW_DATA_CREDIT","statement":"Uma equipe reutiliza um gráfico de fonte pública em uma apresentação. O que precisa constar na versão final?","options":["Somente o endereço do site em letras invisíveis.","A conclusão do grupo sem indicar a origem.","Fonte, data e contexto dos dados, além de verificar condições de reutilização e preservar o sentido original.","A autoria da imagem, sem explicar o período dos dados."],"correctAnswer":"Fonte, data e contexto dos dados, além de verificar condições de reutilização e preservar o sentido original.","explanation":"Atribuição e contexto permitem rastrear e interpretar os dados; também é preciso respeitar as condições de uso.","hint":"O que outra pessoa precisa saber para localizar e interpretar o gráfico?","errorFocus":"Atribuir sem contexto ou sem condição de uso","misconceptions":{"Somente o endereço do site em letras invisíveis.":["HIDDEN_SOURCE"],"A conclusão do grupo sem indicar a origem.":["UNSOURCED_CLAIM"],"A autoria da imagem, sem explicar o período dos dados.":["CREDIT_WITHOUT_CONTEXT"]},"authoringOrder":31,"position":5},{"id":"v5-lgg301-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"REFLECT","contextFamily":"REVIEW_UNEVEN_PARTICIPATION","statement":"No balanço do projeto, uma pessoa relata que quase não conseguiu participar das decisões. Que resposta produz evidência útil para o próximo trabalho?","options":["Responder que todos tiveram a mesma oportunidade porque havia uma reunião.","Atribuir a dificuldade apenas à personalidade da pessoa.","Retirar o relato do registro para evitar conflito.","Registrar o relato sem exposição desnecessária, rever como decisões e falas foram distribuídas e combinar uma mudança verificável."],"correctAnswer":"Registrar o relato sem exposição desnecessária, rever como decisões e falas foram distribuídas e combinar uma mudança verificável.","explanation":"A revisão do processo examina práticas e evidências, sem transformar um relato em diagnóstico pessoal.","hint":"Que rotina do grupo pode ser ajustada e observada na próxima atividade?","errorFocus":"Negar experiência por igualdade formal de oportunidade","misconceptions":{"Responder que todos tiveram a mesma oportunidade porque havia uma reunião.":["MEETING_AS_EQUAL_VOICE"],"Atribuir a dificuldade apenas à personalidade da pessoa.":["PERSONALIZE_SYSTEMIC_ISSUE"],"Retirar o relato do registro para evitar conflito.":["SUPPRESS_FEEDBACK"]},"authoringOrder":32,"position":6},{"id":"v5-lgg301-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REVIEW_SURVEY_LIMITS","statement":"Uma enquete voluntária recebeu 18 respostas favoráveis à campanha. Qual apresentação do resultado é mais responsável?","options":["Informar número, forma de participação e limite da amostra, sem afirmar que representa todas as pessoas.","Afirmar que a comunidade inteira aprovou.","Ocultar a participação voluntária para simplificar o gráfico.","Usar as respostas como prova de mudança de comportamento."],"correctAnswer":"Informar número, forma de participação e limite da amostra, sem afirmar que representa todas as pessoas.","explanation":"Autoseleção e tamanho limitam generalização; opinião declarada também não equivale a comportamento observado.","hint":"Indique quem respondeu e o que exatamente foi perguntado.","errorFocus":"Confundir respondentes voluntários com amostra representativa","misconceptions":{"Afirmar que a comunidade inteira aprovou.":["VOLUNTEER_SAMPLE_AS_POPULATION"],"Ocultar a participação voluntária para simplificar o gráfico.":["HIDE_METHOD"],"Usar as respostas como prova de mudança de comportamento.":["OPINION_AS_BEHAVIOR"]},"authoringOrder":33,"position":7},{"id":"v5-lgg301-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"CREATE","contextFamily":"REVIEW_AUDIO_DESCRIPTION","statement":"Uma mostra tem cenas visuais importantes que não são descritas na faixa sonora. Que ajuste atende melhor ao público que não vê as imagens?","options":["Narrar cada detalhe decorativo continuamente.","Adicionar descrição objetiva das informações visuais relevantes e testar se cabe nos intervalos sem encobrir falas.","Aumentar a música para indicar que a cena mudou.","Deixar que o título da mostra explique todas as cenas."],"correctAnswer":"Adicionar descrição objetiva das informações visuais relevantes e testar se cabe nos intervalos sem encobrir falas.","explanation":"A descrição prioriza informação visual relevante e precisa ser integrada ao ritmo da obra.","hint":"Identifique quais mudanças visuais são necessárias para acompanhar a sequência.","errorFocus":"Confundir descrição funcional com narração indiscriminada","misconceptions":{"Narrar cada detalhe decorativo continuamente.":["EVERY_DETAIL_NARRATED"],"Aumentar a música para indicar que a cena mudou.":["MUSIC_AS_DESCRIPTION"],"Deixar que o título da mostra explique todas as cenas.":["TITLE_AS_FULL_ACCESS"]},"authoringOrder":34,"position":8},{"id":"v5-lgg301-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"REVISE","contextFamily":"REVIEW_FINAL_RELEASE","statement":"Na última revisão, alguém encontra um telefone pessoal no rodapé da peça, embora o objetivo seja divulgar apenas o horário. O que fazer?","options":["Manter o telefone porque já foi diagramado.","Publicar assim e pedir que a pessoa ignore o dado.","Remover o dado pessoal, confirmar se alguma versão já circulou e seguir o procedimento acordado para substituí-la.","Reenviar o arquivo a mais grupos para corrigir a versão anterior."],"correctAnswer":"Remover o dado pessoal, confirmar se alguma versão já circulou e seguir o procedimento acordado para substituí-la.","explanation":"Minimização de dados e correção de circulação reduzem exposição sem ampliar o alcance indevidamente.","hint":"O telefone é necessário ao propósito? Quem já pode ter recebido a peça?","errorFocus":"Preservar dado pessoal por conveniência de edição","misconceptions":{"Manter o telefone porque já foi diagramado.":["LAYOUT_SUNK_COST"],"Publicar assim e pedir que a pessoa ignore o dado.":["IGNORE_EXPOSURE"],"Reenviar o arquivo a mais grupos para corrigir a versão anterior.":["AMPLIFY_TO_CORRECT"]},"authoringOrder":35,"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-languages-collaboration',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-languages-collaboration' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'LANGUAGES', 'LINGUAGENS_MULTISSEMIOTICAS', 'planejamento colaborativo de producoes em diferentes linguagens',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

